package com.crh.logon.webservices.clients.beans.pricingcall;

import java.io.Serializable;
import java.util.List;

/**
 * @author AdNovum Informatik AG
 * 
 * Data Transfer Object from business tier to the webservice client 
 * tier. This object will be created and filled in the business tier, and 
 * converted/read in the webservices-client tier into the data model for SAP
 * as generated by AXIS.
 * 
 * Represents: ZFSD_PRICE_SIMULATION / {@code ZTSD_PS_ITEMS} 
 */
public class PricingCallDTOItems implements Serializable {

	private static final long serialVersionUID = -7684198228221856465L;
	
	/**
	 * WS field to SAP: ZFSD_PRICE_SIMULATION / ZTSD_PS_ITEMS / item
	 */
	private List<PricingCallDTOItem> items;

	public List<PricingCallDTOItem> getItems() {
		return items;
	}

	public void setItems(List<PricingCallDTOItem> items) {
		this.items = items;
	}

	@Override
	public String toString() {
		return "PricingCallDTOItems [items=" + items + "]";
	}

}